// Shared agent picker for the studio and the Zenith presentation.
window.addEventListener('DOMContentLoaded',()=>{'use strict';
const el=id=>document.getElementById(id),form=el('agent-form');if(!form)return;
const target=form.closest('[data-agent-target]')?.dataset.agentTarget||'scene';
const auth=window.GLYPH_BRIDGE,prompt=el('agent-prompt'),send=el('agent-send'),stop=el('agent-stop'),undo=el('agent-undo'),status=el('agent-status'),response=el('agent-result'),model=el('agent-model'),picker=el('agent-provider'),privacy=el('agent-privacy');
let busy=false,polling=false,latest=null,localMessage='',profileKey='';try{const saved=localStorage.getItem('glyph-agent-provider');if(['hermes','codex'].includes(saved))picker.value=saved;}catch{}
async function api(route,body){const r=await fetch('/api/'+route,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+auth.token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error?.message||'Agent connection failed');return d;}
function render(d){latest=d;busy=d.job?.status==='running';const job=(d.job?.target||'scene')===target?d.job:null;const list=d.providers||[{id:'hermes',connected:d.connected,modelLabel:d.modelLabel}];for(const option of picker.options){const p=list.find(p=>p.id===option.value);option.disabled=!p?.connected;}
 const p=list.find(p=>p.id===picker.value);send.disabled=!p?.connected||busy;picker.disabled=busy;stop.hidden=!busy;undo.disabled=!d.canUndo||busy;
 model.textContent=p?.connected?(picker.value==='codex'?'CODEX / ':'ON-DEVICE / ')+(p.modelLabel||'Connected'):'OFFLINE';privacy.textContent=picker.value==='codex'?'Codex receives your prompt and current '+target+' through your signed-in Codex account.':'Local Hermes uses your on-device model. Prompts and '+target+'s stay on this computer.';
 const profile=d.designer,key=profile?JSON.stringify([profile,picker.value]):'';if(key!==profileKey){profileKey=key;el('designer-info').hidden=!profile;if(profile){el('designer-role').textContent=profile.role+' · '+profile.purpose;el('designer-skills').replaceChildren(...profile.skills.map(skill=>{const li=document.createElement('li');const strong=document.createElement('strong');strong.textContent=skill.name;li.append(strong,document.createTextNode(' — '+skill.description));return li;}));el('designer-tools').textContent=(profile.tools[picker.value]||[]).filter(n=>n.startsWith('glyph_flow_')===(target==='flow')).length+(picker.value==='codex'?' read-only tools · validated proposals.':' scoped tools · revision-checked edits.');el('designer-memory').textContent=profile.memory;}}
 const stages={glyph_flow_read:'Reading flow…',glyph_flow_validate:'Validating flow…',glyph_flow_edit:'Editing draft…',glyph_flow_apply:'Staging flow…',glyph_flow_invoke:'Queuing method call…',glyph_studio_library:'Reading design library…',glyph_studio_audit:'Auditing scene…',glyph_studio_read:'Reading scene…',glyph_studio_update:'Updating layer…',glyph_studio_apply:'Applying scene…',glyph_studio_compile:'Checking recipe…',glyph_studio_add:'Adding layer…',glyph_studio_remove:'Removing layer…',glyph_studio_preview:'Checking playback…'};
 status.textContent=busy?((d.job.provider==='codex'?'Codex · ':'Hermes · ')+(stages[d.job.stage]||d.job.stage)):job?.status==='complete'?'Complete':job?.status==='undone'?'Undone':job?.status==='failed'?'Needs attention':job?.status==='cancelled'?'Stopped':p?.connected?'Ready':'Connect the selected agent';
 response.textContent=localMessage||job?.message||'';
}
async function poll(){if(polling||!auth)return;polling=true;try{render(await api('agent?provider='+picker.value+'&target='+target));}catch(e){send.disabled=true;status.textContent='Disconnected';localMessage=e.message;response.textContent=e.message;}finally{polling=false;}}
picker.onchange=()=>{localMessage='';try{localStorage.setItem('glyph-agent-provider',picker.value);}catch{}if(latest)render(latest);poll();};
form.onsubmit=async e=>{e.preventDefault();if(busy||!auth)return;send.disabled=true;localMessage='';response.textContent='';try{
 if(target==='flow')await window.glyphFlowStudio?.flush();
 if(target==='scene'&&window.glyphStudio){if(window.glyphStudio.hasUnbuiltChanges())throw Error('Build your directive or inspector changes before prompting the agent.');await window.glyphBridge?.publish(window.glyphStudio.getScene());const saved=await api('state');if(JSON.stringify(saved.scene)!==JSON.stringify(window.glyphStudio.getScene()))throw Error('The built scene is still syncing. Resolve any scene conflict, then try again.');}
 render(await api('agent',{prompt:prompt.value,provider:picker.value,target}));
 }catch(e){localMessage=e.message;response.textContent=e.message;send.disabled=false;}};
stop.onclick=async()=>{try{render(await api('agent/cancel',{}));}catch(e){localMessage=e.message;response.textContent=e.message;}};
undo.onclick=async()=>{undo.disabled=true;try{await api('agent/undo',{target});await poll();}catch(e){localMessage=e.message;response.textContent=e.message;}};
prompt.onkeydown=e=>{if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();form.requestSubmit();}};
if(auth){poll();setInterval(()=>{if(!document.hidden)poll();},700);}else{send.disabled=true;picker.disabled=true;model.textContent='STANDALONE';status.textContent='Open the local studio to connect';privacy.textContent='Run the dev server and open http://127.0.0.1:8788/ to use Hermes or Codex.';}
});
